#!/usr/bin/env python3
"""Apply exactly eight SHA-measured P86 safe patches on a complete P85 source."""
from pathlib import Path
import sys, json, hashlib, shutil
root=Path(sys.argv[1]).resolve()
here=Path(__file__).resolve().parent
changes=json.loads(r'''[{"path":"app/src/main/java/com/ab/khatma/secure/KhatmaVisualHome.kt","before":"b3108a6a6b1938be016ac866a62f8b554644649d2e2be6a041cb80376a175cb7","after":"d55f8712b00ba005f16cb7ec9683f9f9aa5a3b94355b548f87431629e33f8796","pairs":[["        OutlinedButton(onClick=onOpenIbtehal,modifier=Modifier.fillMaxWidth().target(\"home.ibtehal\"),shape=RoundedCornerShape(16.dp)) { Text(\"♫ الابتهالات والتواشيح\",color=dark) }\n",""]]},{"path":"app/src/main/java/com/ab/khatma/secure/SecureV2Screen.kt","before":"b5f43e25fda31f9c7848cfda64e68c3bafd75df4c669b09617e6eb0983189578","after":"46af4f5f381e54200f21928619124a260ee72c8372b799f22eaf3f24138039eb","pairs":[["PrayerPremiumScreen(onBack = { section = \"home\" })","PrayerPremiumScreen(onBack = { section = \"home\" }, onOpenIbtehal = { section = \"ibtehal\" })"],["com.ab.khatma.ui.screens.P85IbtehalScreen(onBack = { section = \"home\" })","com.ab.khatma.ui.screens.P85IbtehalScreen(onBack = { section = \"prayer\" })"]]},{"path":"app/src/main/java/com/ab/khatma/ui/screens/PrayerPremiumScreen.kt","before":"f2894efb43260e42872089a7d7f6ae787781e4dac589344c3eba4b808a8d7449","after":"37eadd36651c85850545c3c0a9eba08d703449a078b0983849b72490f891085c","pairs":[["fun PrayerPremiumScreen(onBack: () -> Unit) {","fun PrayerPremiumScreen(onBack: () -> Unit, onOpenIbtehal: () -> Unit = {}) {"],["            item {\n                PrayerHeroCard(","            item {\n                OutlinedButton(\n                    onClick = onOpenIbtehal,\n                    modifier = Modifier.fillMaxWidth().heightIn(min = 42.dp),\n                    shape = RoundedCornerShape(16.dp),\n                ) { Text(\"♫ الابتهالات والتواشيح\", color = DeepGreen, fontWeight = FontWeight.Bold) }\n            }\n            item {\n                PrayerHeroCard("],["Text(\"أذان الشيوخ — إسلام ويب\",color=DeepGreen,fontSize=16.sp,fontWeight=FontWeight.Bold)","Text(\"أذان بأصوات القراء\",color=DeepGreen,fontSize=16.sp,fontWeight=FontWeight.Bold)"]]},{"path":"app/src/main/java/com/ab/khatma/guide/P85Guide.kt","before":"3a4a61c4280f6b9ca1700af1da50cc75421f0a502a7c28e7aba55d6dad710c8b","after":"b6299d6f1d7c5e72aceb937d98c76cd6560b10eb30f6771962f117cb31533010","pairs":[["            GuideStep(\"home.profile\", \"حسابك والإعدادات\", \"من حسابي تقدر تضبط الاسم والقارئ والتنبيهات. زر شرح التطبيق هنا بيرجّع الدليل وقت ما تحب.\"),\n            GuideStep(\"home.ibtehal\", \"الابتهالات\", \"افتح بث الابتهالات والتواشيح أو تسجيلات الأرشيف من مصادرها. الاستماع هنا اختياري ويحتاج إنترنت.\"))),","            GuideStep(\"home.profile\", \"حسابك والإعدادات\", \"من حسابي تقدر تضبط الاسم والقارئ والتنبيهات. زر شرح التطبيق هنا بيرجّع الدليل وقت ما تحب.\"))),"],["            GuideStep(\"\", \"أذونات الهاتف\",","            GuideStep(\"\", \"الابتهالات\", \"تلاقي الابتهالات والتواشيح داخل قسم الصلاة والأذان. تشغيل التسجيلات باختيارك فقط.\"),\n            GuideStep(\"\", \"أذونات الهاتف\","]]},{"path":"app/src/main/java/com/ab/khatma/ui/screens/P41OfflineMushafPage.kt","before":"9df48b5b1cdaf181b20e9c2f11f8f6c35ffe16273ebfa856b2db80fa52fececb","after":"6b2f5964eccfefb7e3852eb327f28be318d9ad58b54730675a0ec60b48fd8bd0","pairs":[["            P85OriginalTitleFrames(frames, page.width, page.height, Modifier.fillMaxSize())\n            selectedHighlight?.let","            P85OriginalTitleFrames(frames, page.width, page.height, Modifier.fillMaxSize())\n            P86PageFooter(page, pageNumber, paperFilter, Modifier.fillMaxSize())\n            selectedHighlight?.let"],["            colorFilter = paperFilter,\n        )\n        val textTop = max(headerY","            colorFilter = paperFilter,\n        )\n        // Reading mode composites the original footer separately: the same source\n        // image geometry is reused for the ornament, not guessed from screen dp.\n        withTransform({\n            translate(0f,footerY.toFloat())\n            scale(w.toFloat()/page.width,footerDstH.toFloat()/footerHeight,Offset.Zero)\n            translate(0f,-footerSrcY.toFloat())\n        }) { p86OriginalFooter(page,pageNumber,paperFilter) }\n        val textTop = max(headerY"],["            if (decorated) P85OriginalTitleFrames(titleFrames, page.width, page.height,\n                Modifier.fillMaxSize().graphicsLayer(\n                    scaleX=actualScale, scaleY=actualScale,\n                    translationX=focusOffsets(actualScale).first+x,\n                    translationY=focusOffsets(actualScale).second+y))","            if (decorated) {\n                val samePageTransform = Modifier.fillMaxSize().graphicsLayer(\n                    scaleX=actualScale, scaleY=actualScale,\n                    translationX=focusOffsets(actualScale).first+x,\n                    translationY=focusOffsets(actualScale).second+y)\n                P85OriginalTitleFrames(titleFrames, page.width, page.height, samePageTransform)\n                P86PageFooter(page,pageNumber,\n                    if (P53NightMode.enabled) P53NightMode.pageFilter else if (P67Look.white) P67Look.pageFilter else null,\n                    Modifier.fillMaxSize().graphicsLayer(\n                        scaleX=actualScale, scaleY=actualScale,\n                        translationX=focusOffsets(actualScale).first+x,\n                        translationY=focusOffsets(actualScale).second+y))\n            }"]]},{"path":"app/src/main/java/com/ab/khatma/ui/screens/AppRoot.kt","before":"5009b02e0389a3836c4073b6e651862125c752ca5b12af50a5bb17aeb1a59c04","after":"d3fd4931b8abaf51491b70db444db4fe21a30f7af0fa3c0357f4b53e531062a3","pairs":[["    data object PrayerSettings : Screen\n","    data object PrayerSettings : Screen\n    data object Ibtehal : Screen\n"],["        Screen.PrayerSettings -> PrayerPremiumScreen(onBack = { screen = Screen.Home })","        Screen.PrayerSettings -> PrayerPremiumScreen(onBack = { screen = Screen.Home }, onOpenIbtehal = { screen = Screen.Ibtehal })\n        Screen.Ibtehal -> P85IbtehalScreen(onBack = { screen = Screen.PrayerSettings })"]]},{"path":"app/build.gradle.kts","before":"3043e97c1a0e72d2c3bfaacd3886af77af35ac62ee0c78c83529a39c4316e62b","after":"864f257aba83751bb9238c3f33a53d01176675fd67e321080fc764b16b0312d6","pairs":[["versionCode = 109","versionCode = 110"],["0.19.80-p85-guide-adhan-safe","0.19.81-p86-folio-navigation-safe"]]}]''')
digest=lambda p:hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() else None
new_rel="app/src/main/java/com/ab/khatma/ui/screens/P86PageFooter.kt"
new=here/"overlay"/new_rel
assert digest(new)=="a413033eeac740239bd072bcc18d9080746b7e5baa26c4fa1e7533c5d82419bb", "Untrusted new ornament source"
assert not (root/new_rel).exists(), "P86 ornament already present"
prepared=[]
for item in changes:
    target=root/item["path"]
    assert digest(target)==item["before"],"Baseline mismatch "+item["path"]
    value=target.read_text()
    for old,replacement in item["pairs"]:
        assert value.count(old)==1, "Unexpected patch anchor "+item["path"]
        value=value.replace(old,replacement,1)
    assert hashlib.sha256(value.encode()).hexdigest()==item["after"],"Result mismatch "+item["path"]
    prepared.append((target,value))
# Transaction-like pre-validation: zero files are written before all patches pass.
for target,value in prepared:
    target.write_text(value)
output=root/new_rel
output.parent.mkdir(parents=True,exist_ok=True)
shutil.copyfile(new,output)
for item in changes:
    assert digest(root/item["path"])==item["after"],"Post-write hash mismatch "+item["path"]
assert digest(output)=="a413033eeac740239bd072bcc18d9080746b7e5baa26c4fa1e7533c5d82419bb"
print("P86: eight old files SHA verified; one new folio file; all original Quran assets untouched.")
